#[derive(Clone)]
struct Point {
    x: i32,
    y: i32,
}

fn magnitude(p: Point) -> f64 {
    ((p.x * p.x + p.y * p.y) as f64).sqrt()
}

fn describe(p: Point) -> String {
    format!("({}, {}) is {:.1} away", p.x, p.y, magnitude(p.clone()))
}

fn report() -> String {
    let p = Point { x: 3, y: 4 };
    let m = magnitude(p.clone());
    format!("{} | mag {m:.1}", describe(p))
}

